"""Network Setup uses the shared Moon Cheese collapsible panel styles."""
NETWORK_PANEL = '''<details class="panel setting-section" id="network-admin" {% if show_network %}open{% endif %}><summary>Network and remote access</summary><div class="setting-content">
<p class="note">Administrator-only. Choose one method of access. The existing external reverse proxy can remain managed outside Moon Cheese. Nothing changes until you submit a form and confirm with your administrator password. <a href="{{url_for('help_page')}}#network-setup">Full network setup Help →</a></p>
<div class="notice"><strong>Local IP address:</strong> {{pi_lan or 'Not detected'}} — the NPM administrator is restricted to this device. Use an SSH tunnel from another computer. Never forward ports 8000 or 8181 publicly.</div>
<details class="panel setting-section"><summary>Local network only (no public domain)</summary><div class="setting-content"><p class="note">The simplest and default option. Keep the dashboard private on your home network. Choosing this does not delete an existing tunnel, DNS record, NPM configuration or router rule: review those independently.</p>
<h3>Local network addresses</h3><p class="note">Actual connected Ethernet and Wi-Fi addresses on this device; Docker bridges are excluded. The links open Moon Cheese locally (sign-in required). A link may not work if your computer is on a different network.</p>
<div id="network-address-list">{% for nic in network_interfaces if nic.connection and nic.address %}
<p><strong>{{'Wi-Fi' if nic.kind=='wifi' else 'Ethernet'}} ({{nic.device}}):</strong> <a href="http://{{nic.address}}:8000/" target="_blank" rel="noopener">{{nic.address}}</a> — {{nic.address_mode}}</p>
{% else %}<p class="note">No active physical IPv4 addresses detected.</p>{% endfor %}</div>
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="local"><label>Confirm administrator password<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">Select local-only mode</button></form><div class="notice network-inline-result" data-network-status="local" role="status" {% if not network_status_map.get("local") %}hidden{% endif %}>{% set last=network_status_map.get("local") %}{% if last %}<strong>Local network — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div></div></details>
<details class="panel setting-section" {% if focus_network in ('npm','npm_apply','npm_change') %}open{% endif %}><summary>Cloudflare domain + NPM on this device</summary><div class="setting-content">
<p class="note">Enter the hostname and Cloudflare details, then select <strong>Set up or update</strong>. Moon Cheese checks existing resources, configures the proxy and SSL, and updates only the selected DNS hostname. Previously working proxy hosts are kept until the replacement is ready. Other NPM installations are untouched.</p>
{% if managed_domain and managed_domain.hostname and managed_domain.npm_host_enabled %}<div class="notice"><strong>Previously configured domain:</strong> {{managed_domain.hostname}}{% if managed_domain.mode=='npm' %} — Managed NPM/DDNS enabled{% else %} — Currently in local mode; settings retained{% endif %}</div>{% endif %}
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="npm_apply">
<label>Detector hostname <input name="hostname" required placeholder="camera.example.com" value="{{managed_domain.hostname or ''}}" autocomplete="off"></label>
<label>Cloudflare Zone ID <input name="zone" maxlength="32" required autocomplete="off" value="{{managed_domain.zone or ''}}"></label>
<label>Cloudflare API token <input name="token" type="password" {% if not managed_domain.credentials_saved %}required{% endif %} autocomplete="new-password" placeholder="{% if managed_domain.credentials_saved %}Already saved — leave blank to reuse{% else %}Enter your scoped Cloudflare token{% endif %}"></label>
<label>Let's Encrypt contact email <input name="email" type="email" maxlength="254" required autocomplete="email" value="{{managed_domain.certificate_contact_email or ''}}" placeholder="you@example.com"></label>
<p class="note">NPM uses its administrator email for Let's Encrypt. If the contact email is different, saving it also changes the local NPM administrator login email. The new address will be shown in this form.</p>
<label>Confirm administrator password <input type="password" name="password" required autocomplete="current-password"></label>
<button type="submit">Set up or update NPM and Cloudflare</button></form>
<p class="note">Automatic DDNS checks every five minutes. Router forwarding for local NPM: external TCP 80 → this device TCP 8080; external TCP 443 → TCP 8443. Never forward dashboard port 8000 or NPM administration port 8181 publicly. Reserve the device's LAN address in your router where possible.</p>
<p class="note">Find the Zone ID under Cloudflare → Domain Overview. Create a scoped token with Zone DNS Edit and Zone Read. Moon Cheese does not alter unrelated hostnames or other reverse proxies.</p>
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="ddns_check"><button type="submit">Check DDNS now</button></form>
<div class="notice network-inline-result" data-network-status="npm_apply" role="status" {% if not network_status_map.get('npm_apply') %}hidden{% endif %}>{% set last=network_status_map.get('npm_apply') %}{% if last %}<strong>NPM + Cloudflare — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div>
<div class="notice network-inline-result" data-network-status="ddns_check" role="status" {% if not network_status_map.get('ddns_check') %}hidden{% endif %}>{% set last=network_status_map.get('ddns_check') %}{% if last %}<strong>DDNS — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div>
{% if managed_domain.previous_hostname %}<details class="setting-section"><summary>Previous managed domain</summary><div class="setting-content"><p class="note">Previous: {{managed_domain.previous_hostname}}. The old DNS record and certificate are preserved. After you have verified your new public HTTPS address, you can disable the previous Moon Cheese proxy without deleting its DNS or certificate.</p>
<form action="{{url_for('network_action')}}" method="post"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="npm_retire_old"><input type="hidden" name="hostname" value="{{managed_domain.hostname}}"><label>Confirm administrator password <input type="password" name="password" required autocomplete="current-password"></label><button type="submit">Disable previous proxy</button></form>
<div class="notice network-inline-result" data-network-status="npm_retire_old" role="status" hidden></div></div></details>{% endif %}
</div></details>
<details class="panel setting-section" {% if focus_network in ('tunnel','tunnel_apply','tunnel_abandon','tunnel_cleanup','tunnel_disable','tunnel_remove') %}open{% endif %}><summary>Cloudflare Tunnel — no router forwarding or NPM required</summary><div class="setting-content">
<p class="note">Enter a hostname, Cloudflare account and token, then select <strong>Set up or update</strong>. Moon Cheese finds a previous unfinished setup, repairs its DNS route where safe, installs cloudflared and checks the connection. No NPM or inbound router ports required.</p>
<details class="setting-section"><summary>Cloudflare setup guide — find IDs and create the correct API token</summary><div class="setting-content">
<p class="note"><strong>Before you begin:</strong> add your domain to your own Cloudflare account and ensure its DNS is managed by Cloudflare. You need an administrator login to Cloudflare. Do not borrow another person's API token.</p>
<ol>
<li>Sign in to <a href="https://dash.cloudflare.com/" target="_blank" rel="noopener noreferrer">Cloudflare Dashboard</a>. Select the account that owns the domain. Copy the <strong>Account ID</strong> from that account's overview/details.</li>
<li>Open <strong>Websites</strong>, select your domain (the main domain, not the Moon Cheese subdomain), then find and copy the <strong>Zone ID</strong> under its Overview / API details.</li>
<li>In Cloudflare, open your profile menu → <strong>My Profile → API Tokens → Create Token → Create Custom Token</strong> (the location may also be called Account API Tokens). Name it something like <em>Moon Cheese Tunnel</em>.</li>
<li>In <strong>Permissions</strong>, add <strong>Account → Cloudflare Tunnel → Edit</strong> (some Cloudflare accounts show this as <strong>Cloudflare One Connectors Write</strong> / <strong>Cloudflare One Connector: cloudflared Write</strong>), then <strong>Zone → DNS → Edit</strong>, and <strong>Zone → Zone → Read</strong> (needed to verify that the hostname belongs to your domain). Do not choose a Global API Key.</li>
<li>In <strong>Account Resources</strong> select only the account that owns your domain. In <strong>Zone Resources</strong> choose <strong>Include → Specific zone</strong>, then select your domain. Review the scope and create the token.</li>
<li><strong>Copy the token immediately</strong> into the Moon Cheese API token field below. Cloudflare may only show it once. Keep it secret and do not paste it into chats or screenshots.</li>
<li>Enter a hostname such as <strong>space.example.com</strong>, the Account ID and Zone ID, then confirm with your Moon Cheese administrator password and choose <strong>Set up or update Cloudflare Tunnel</strong>. The hostname must belong to the selected zone.</li>
</ol>
<p class="note">The API token is <strong>not</strong> the tunnel connector token. Moon Cheese creates and stores the connector credentials itself. No port forwarding, NPM or antenna is required. Cloudflare's menu labels change over time; use the listed permission names and scopes.</p>
<p class="note"><strong>Error 1033:</strong> Cloudflare cannot find a healthy tunnel connector. Check <strong>Cloudflare → Networking → Tunnels</strong> for Healthy/Down and check the Moon Cheese Tunnel status. A stopped connector, lost outbound network access, or a DNS hostname pointing to another tunnel may cause it. Do not delete DNS records or tunnels belonging to other services.</p>
</div></details>

{% if managed_tunnel.managed %}<div class="notice"><strong>Previously configured Tunnel:</strong> {{managed_tunnel.hostname}} — {% if managed_tunnel.mode=='tunnel' %}selected for remote access{% else %}configuration saved (currently local mode){% endif %}</div>{% endif %}
{% if managed_tunnel.unfinished %}<div class="notice"><strong>Unfinished Moon Cheese Tunnel:</strong> {{managed_tunnel.stage_hostname}}. You can retry it or enter a different hostname below. You do not need to delete the old Cloudflare resources manually.</div>{% endif %}
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="tunnel_apply">
<label>Detector hostname <input name="hostname" required placeholder="tunnel.example.com" value="{{managed_tunnel.hostname or managed_tunnel.stage_hostname or ''}}"></label>
<label>Cloudflare Account ID <input name="account" maxlength="32" required value="{{managed_tunnel.account or ''}}"></label>
<label>Cloudflare Zone ID <input name="zone" maxlength="32" required value="{{managed_tunnel.zone or ''}}"></label>
<label>Cloudflare API token <input name="token" type="password" {% if not managed_tunnel.credentials_saved %}required{% endif %} autocomplete="new-password" placeholder="{% if managed_tunnel.credentials_saved %}Already saved — leave blank to reuse{% else %}Enter a token with Tunnel Edit and DNS Edit permissions{% endif %}"></label>
<label>Confirm administrator password <input type="password" name="password" required autocomplete="current-password"></label>
<button type="submit">Set up or update Cloudflare Tunnel</button></form>
<p class="note">Find your Account ID in Cloudflare account details and Zone ID on the domain's Overview. The API token needs Account Cloudflare Tunnel Edit, Zone DNS Edit and Zone Read. Moon Cheese keeps any previous working connector active while a replacement is verified. Unrelated live Tunnels and DNS services are protected.</p>
<div class="notice network-inline-result" data-network-status="tunnel_apply" role="status" {% if not network_status_map.get('tunnel_apply') %}hidden{% endif %}>{% set last=network_status_map.get('tunnel_apply') %}{% if last %}<strong>Cloudflare Tunnel — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div>
<details class="setting-section"><summary>Stop or remove Tunnel (optional)</summary><div class="setting-content"><p class="note">Disable stops the connector but keeps the Tunnel and DNS record for later use. Remove permanently deletes only the verified Moon Cheese-managed resources. Keep another way of accessing the detector before removing remote access.</p>
{% if managed_tunnel.managed %}
{% if managed_tunnel.mode=='tunnel' %}<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="tunnel_disable"><input type="hidden" name="hostname" value="{{managed_tunnel.hostname}}"><label>Administrator password <input name="password" type="password" required autocomplete="current-password"></label><button type="submit">Disable Tunnel (keep settings)</button></form>{% endif %}
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="tunnel_remove"><input type="hidden" name="hostname" value="{{managed_tunnel.hostname}}"><label>Administrator password <input name="password" type="password" required autocomplete="current-password"></label><button type="submit" class="danger">Remove managed Tunnel and DNS</button></form>
{% endif %}
{% if managed_tunnel.unfinished %}<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="tunnel_cleanup"><input type="hidden" name="hostname" value="{{managed_tunnel.stage_hostname}}"><label>Cloudflare API token with Tunnel and DNS permissions <input name="token" type="password" required autocomplete="new-password"></label><label>Administrator password <input name="password" type="password" required autocomplete="current-password"></label><button type="submit" class="danger">Remove unfinished Tunnel and DNS</button></form>{% endif %}
<div class="notice network-inline-result" data-network-status="tunnel_disable" role="status" hidden></div>
<div class="notice network-inline-result" data-network-status="tunnel_remove" role="status" hidden></div>
<div class="notice network-inline-result" data-network-status="tunnel_cleanup" role="status" hidden></div>
</div></details>
</div></details>
<details class="panel setting-section"><summary>Use an existing external reverse proxy</summary><div class="setting-content"><p class="note">When your NPM/reverse proxy is on another Pi or server, continue configuring it there. Moon Cheese will not request its administrator credentials or change its settings. Save the public URL under <strong>Notification email links → Optional HTTPS domain</strong> above.</p></div></details>
<details class="panel setting-section" {% if focus_network in ('wifi_scan','wifi_connect','wifi_radio') %}open{% endif %}><summary>Wi-Fi: enable, scan and connect</summary><div class="setting-content">
<p class="note">Configure wireless connections separately from Ethernet. Where possible, keep Ethernet connected while first setting up Wi-Fi. An existing Wi-Fi connection will not be replaced remotely without a wired maintenance connection.</p>
{% for nic in network_interfaces if nic.kind=='wifi' %}<p class="note"><strong>Wireless interface:</strong> {{nic.device}} — {{nic.state}}{% if nic.connection %} ({{nic.connection}}){% endif %}</p>{% endfor %}
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="wifi_radio">
<p class="note" id="network-wifi-radio-state">Wi-Fi currently: <strong>{{wifi_radio_state|title}}</strong></p>
<label>Wi-Fi radio <select name="enabled" id="network-wifi-radio-choice"><option value="yes" {% if wifi_radio_state=='enabled' %}selected{% endif %}>Enable Wi-Fi</option><option value="no" {% if wifi_radio_state=='disabled' %}selected{% endif %}>Disable Wi-Fi</option></select></label>
<label>Confirm administrator password <input type="password" name="password" autocomplete="current-password" required></label>
<label class="checkline"><input name="ack" type="checkbox" value="yes" required> I understand that disabling Wi-Fi may disconnect wireless clients.</label><button type="submit">Apply Wi-Fi radio setting</button></form>
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="wifi_scan">
<label>Wireless interface <select name="interface">{% for nic in network_interfaces if nic.kind=='wifi' %}<option value="{{nic.device}}">{{nic.device}}</option>{% endfor %}</select></label><button type="submit">Scan for nearby Wi-Fi networks</button></form>
<p class="note" id="network-scan-progress">Scan results will appear automatically when ready.</p>
<div id="network-wifi-scan-results">{% if wifi_networks %}<p class="note">Last completed scan:</p><ul>{% for found in wifi_networks %}<li><button type="button" class="network-select-ssid" data-ssid="{{found.ssid|e}}">{{found.ssid}}</button> ({{found.signal}}% signal, {{found.security}})</li>{% endfor %}</ul>{% endif %}</div>
<form method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="wifi_connect">
<label>Wireless interface <select name="interface">{% for nic in network_interfaces if nic.kind=='wifi' %}<option value="{{nic.device}}">{{nic.device}}</option>{% endfor %}</select></label>
<label>Wi-Fi network name (SSID) <input id="network-wifi-ssid" name="ssid" required maxlength="32" autocomplete="off"></label>
<label>Wi-Fi password (WPA2/WPA3 Personal) <input type="password" name="wifi_password" required autocomplete="new-password"></label>
<label>Confirm administrator password <input type="password" name="password" required autocomplete="current-password"></label>
<label class="checkline"><input type="checkbox" name="ack" value="yes" required> I authorise connecting this device to the selected Wi-Fi network.</label>
<button type="submit">Connect to Wi-Fi</button></form>
<p class="note">Enterprise 802.1X and hidden-network setup are not automated. The wireless password is sent only to the local administrator endpoint and is never displayed in status logs or portable backups.</p><div class="notice network-inline-result" data-network-status="wifi_radio" role="status" {% if not network_status_map.get("wifi_radio") %}hidden{% endif %}>{% set last=network_status_map.get("wifi_radio") %}{% if last %}<strong>Wi-Fi radio — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div><div class="notice network-inline-result" data-network-status="wifi_scan" role="status" {% if not network_status_map.get("wifi_scan") %}hidden{% endif %}>{% set last=network_status_map.get("wifi_scan") %}{% if last %}<strong>Wi-Fi scan — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div><div class="notice network-inline-result" data-network-status="wifi_connect" role="status" {% if not network_status_map.get("wifi_connect") %}hidden{% endif %}>{% set last=network_status_map.get("wifi_connect") %}{% if last %}<strong>Wi-Fi connection — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div>
</div></details>
<details class="panel setting-section" {% if focus_network=='ip_change' %}open{% endif %}><summary>IP address: DHCP reservation and advanced static IPv4</summary><div class="setting-content">
<p class="note"><strong>Recommended:</strong> leave the device using DHCP and reserve its current IP in your router. You will find the network interface MAC address in the router's connected devices. A router reservation does not require changing Linux networking.</p>
<p class="note"><strong>Advanced (NetworkManager only):</strong> the following can switch DHCP → static, static → DHCP, or static → different static. A separate systemd rollback restores the previous configuration automatically unless you confirm through the NEW address within 120 seconds. Work from a local device, and keep physical access to the device for recovery.</p>
<form id="network-ip-form" method="post" action="{{url_for('network_action')}}"><input type="hidden" name="csrf" value="{{csrf}}"><input type="hidden" name="action" value="ip_change">
<label>Network interface <select name="interface" id="network-ip-interface" required>{% for nic in network_interfaces if nic.connection %}<option value="{{nic.device}}" data-ip="{{nic.address}}" data-method="{{nic.address_mode}}" data-connection="{{nic.connection}}" data-kind="{{nic.kind}}">{{'Wi-Fi' if nic.kind=='wifi' else 'Ethernet'}} — {{nic.device}} ({{nic.connection}})</option>{% endfor %}</select></label>
<div class="notice" id="network-selected-interface"><strong>Current selected interface:</strong> <span id="network-selected-kind">Checking…</span> · <strong>IPv4:</strong> <span id="network-selected-ip">Checking…</span> · <strong>Assignment:</strong> <span id="network-selected-mode">Checking…</span> · <strong>Connection:</strong> <span id="network-selected-connection">Checking…</span></div>
<div id="network-ip-alternates" class="note">If this connection becomes unreachable, use another connected Ethernet/Wi-Fi address or local console to reach Moon Cheese and view the pending confirmation. DHCP addresses can change.</div>
<label>Address mode <select name="mode" id="network-ip-mode"><option value="dhcp">Obtain address automatically (DHCP)</option><option value="static">Use a static IPv4 address</option></select></label>
<div id="network-static-fields" hidden>
<label>Static IPv4 address <input name="ip" placeholder="192.168.1.50"></label>
<label>Subnet prefix (often 24) <input name="prefix" type="number" min="1" max="30" value="24"></label>
<label>Router gateway <input name="gateway" placeholder="192.168.1.1"></label>
<label>DNS server(s), optional <input name="dns" placeholder="192.168.1.1 1.1.1.1"></label></div>
<label>Confirm administrator password <input type="password" name="password" required autocomplete="current-password"></label>
<label class="checkline"><input type="checkbox" name="ack" value="yes" required> I understand the connection may briefly drop, and will confirm from the new address or wait for automatic restoration.</label>
<button type="submit">Apply temporarily and test connection</button></form>
<div id="network-ip-expected" class="notice" hidden><strong>Expected new static IP confirmation address</strong> — copy this before applying the change: <a id="network-ip-expected-link" href="#" target="_blank" rel="noopener"></a><p class="note">This link works only once NetworkManager has applied the new address. If changing your only connection, the original tab or page may become unable to refresh. For DHCP the new address is assigned by your router and cannot be guaranteed in advance. Stay connected through another physical interface when possible; once the device confirms the new DHCP lease, the permanent link will appear automatically if this tab can still contact it.</p></div>
<div id="network-ip-progress" class="notice" {% if not pending_network %}hidden{% endif %}><strong>Checking network change.</strong> If you cannot reach the new address, do nothing: the original settings will return automatically. <p>Time remaining: <strong id="network-ip-countdown">Waiting for verification</strong></p><p><a id="network-ip-new-link" href="{% if pending_network and pending_network.new_ip %}http://{{pending_network.new_ip}}:8000/system/network/confirm{% else %}#{% endif %}" target="_blank" rel="noopener" {% if not pending_network or not pending_network.new_ip %}hidden{% endif %}>Open new IP confirmation page{% if pending_network and pending_network.new_ip %}: http://{{pending_network.new_ip}}:8000/system/network/confirm{% endif %}</a></p><p id="network-ip-message">If the link will not open from your public HTTPS domain, copy the address into a new browser tab. For DHCP the link will appear after the assigned address is verified, provided this tab remains reachable. The independent rollback continues even when both tabs are closed.</p></div>
<div class="notice network-inline-result" data-network-status="ip_change" role="status" {% if not network_status_map.get("ip_change") %}hidden{% endif %}>{% set last=network_status_map.get("ip_change") %}{% if last %}<strong>IP address — {{last.state|title}}</strong>: {{last.message}} <small>({{last.time or ''}})</small>{% endif %}</div>{% if pending_network and pending_network.new_ip %}<p class="note"><strong>Pending change:</strong> {{pending_network.mode}} to {{pending_network.new_ip or 'DHCP (address being discovered)'}}. <a href="http://{{pending_network.new_ip}}:8000/system/network/confirm" target="_blank" rel="noopener">Open confirmation at the new address</a>; if your browser blocks it, copy the address and open it manually. Deadline recorded by the device.</p>{% endif %}
<script src="{{url_for('network_ui_js')}}" defer></script>
</div></details>
</div></details>'''

CONFIRM_PAGE = '''<h1>Confirm network connection</h1><div class="panel">
<p class="note">This page must be opened at the <strong>new local IP address</strong>. A fresh administrator login may be required because your browser treats different IP addresses as separate sites.</p>
{% if pending %}<p>New IP address: <strong>{{pending.new_ip or 'Not yet detected'}}</strong></p>
<div class="notice" id="network-confirm-timer" data-deadline="{{pending.expires}}"><strong>Time remaining: <span id="network-confirm-countdown">Checking deadline…</span></strong><p id="network-confirm-help">You must confirm this new connection before the timer expires. Otherwise Moon Cheese automatically restores the previous network settings.</p></div>
<p class="note">The old browser tab does not confirm this change. You must select Keep new address below; simply signing in does not confirm it.</p><form method="post" id="network-confirm-form"><input type="hidden" name="csrf" value="{{csrf}}"><label>Confirm administrator password<input name="password" type="password" required autocomplete="current-password"></label><button type="submit">Yes — keep this new address</button></form>
<script src="{{url_for('network_confirm_js')}}" defer></script>
{% else %}<p>No active change awaits confirmation. If rollback was requested, wait for the original address to return.</p>{% endif %}
</div>'''
